head.script:
scwin.onpageload = function () {
    let taskInfo = $p.getParameter("taskInfo");
    scwin.taskId = taskInfo.taskId;
    scwin.getTaskVersion(scwin.taskId, 1);

    //무한스크롤
    scwin.currentPage = 0;         // 현재 페이지 번호
    scwin.isLoading = false;       // 중복 로딩 방지
    scwin.lastPageReached = false; // 더 이상 데이터 없음

    scwin.loadMoreVersions();
    scwin.bindInfiniteScroll();
};


//task 버전 가져오기
scwin.getTaskVersion = function (taskId, page) {
    const param = {
        taskId: taskId,
        page: page
    };
    dma_taskSearch.setJSON(param);
    sbm_taskVersionList.action = `/InsWebApp/task/${taskId}/version.pwkjson`;
    $c.sbm.execute(sbm_taskVersionList);
}

//현재버전
scwin.addCurrentVersionComponent = function () {
    const group = $p.getComponentById("version_group");

    const buttonId = "taskVersion_button_current";

    const buttonWrapper = $p.dynamicCreate(buttonId, "button", {
        className: "version-button current-version-button"
    }, group);

    const highlightSpan = $p.dynamicCreate("highlight_current", "span", {
        label: "현재버전",
        className: "highlight-text"
    }, buttonWrapper);

    const versionButton = $p.getComponentById(buttonId);
    versionButton.bind("onclick", () => {
        $p.parent().scwin.loadOriginalVersion();
    });
};

//버전 버튼 생성
scwin.addVersionComponent = function (versionData) {
    const group = $p.getComponentById("version_group");
    const buttonId = `taskVersion_button_${versionData.taskVersionId}`;
    const versionId = String(versionData.taskVersionId).padStart(2, "0");

    const buttonWrapper = $p.dynamicCreate(buttonId, "button", {
        className: "version-button"
    }, group);

    const highlightSpan = $p.dynamicCreate(`highlight_${versionData.taskVersionId}`, "span", {
        label: `${versionData.createdAt} 버전`,
        className: "highlight-text"
    }, buttonWrapper);

    const versionButton = $p.getComponentById(buttonId);
    versionButton.bind("onclick", () => {
        scwin.getTaskByTaskVersinId(scwin.taskId, versionData.taskVersionId);
    });

};

//task 버전 불러옴
scwin.sbm_taskVersionList_submitdone = function (e) {
    const responseData = e.responseJSON;
    const versionList = responseData.elData.taskVersionVoList;

    // ⛔ 더 이상 로드할 데이터가 없을 때
    if (!versionList || versionList.length === 0) {
        scwin.lastPageReached = true;
        scwin.isLoading = false;
        return;
    }

    // 첫 로딩이라면 현재버전 버튼 추가
    if (scwin.currentPage === 0) {
        scwin.addCurrentVersionComponent();
    }

    // 버전 버튼 생성
    versionList.forEach((value) => {
        scwin.addVersionComponent(value);
    });

    // ✅ 페이지 증가 + 로딩 해제
    scwin.currentPage += 1;
    scwin.isLoading = false;
    console.log("출력: " + scwin.currentPage);
};

scwin.sbm_taskVersionList_submiterror = function (e) {

};


//버전 아이디로 해당 내용과 파일을 return
scwin.getTaskByTaskVersinId = function (taskId, taskVersionId) {

    // 서버로 전송
    $.ajax({
        url: `/InsWebApp/task/${taskId}/version/${taskVersionId}.pwkjson`,
        type: "GET",
        processData: false,
        contentType: false,
        success: async function (res) {
            $p.parent().scwin.versionLoad(res);
        },
        error: async function (err) {
            await $c.win.alert("버전 조회 실패");
        }
    });
}

//무한스크롤
scwin.bindInfiniteScroll = function () {
    const container = $p.getComponentById("version_group");

    container.bind("onscroll", function () {
        if (scwin.isLoading || scwin.lastPageReached) return;

        const scrollTop = container.render.scrollTop;
        const scrollHeight = container.render.scrollHeight;
        const clientHeight = container.render.clientHeight;

        if (scrollTop + clientHeight >= scrollHeight - 50) {
            scwin.loadMoreVersions();
        }
    });
};

//task 버전들 가져오기
scwin.loadMoreVersions = function () {
     console.log("로딩출력: " + scwin.currentPage);
    if (scwin.isLoading || scwin.lastPageReached) return;

    scwin.isLoading = true;
    const nextPage = scwin.currentPage + 1;


    const param = {
        taskId: scwin.taskId,
        page: nextPage
    };

    dma_taskSearch.setJSON(param);
    sbm_taskVersionList.action = `/InsWebApp/task/${scwin.taskId}/version.pwkjson`;
     console.log(sbm_taskVersionList.action);

    // 콜백에서 현재 페이지 업데이트
    $c.sbm.execute(sbm_taskVersionList);
};
